type LinkItem = { title: string; url: string };
type Bookmark = { title: string; url: string; createdAt: string };
type ReadingItem = { title: string; url: string; savedAt: string };
type SavedSearch = { query: string; savedAt: string };
type SearchHistoryItem = { query: string; searchedAt: string };
type HistoryItem = { title: string; url: string; visitedAt: string };
type IndexedDocument = { title: string; url: string; text: string; headings: string[]; links: LinkItem[]; indexedAt: string };
type GraphDocument = { title: string; url: string; indexedAt: string; links: LinkItem[] };
type Note = { id: number; quote: string; body: string; tags: string[]; sourceUrl: string; sourceTitle: string; createdAt: string };
type GraphData = { documents: GraphDocument[]; notes: Note[] };
type SearchResult = { kind: "document"; title: string; url: string; headings: string[]; preview: string; indexedAt: string } | { kind: "note"; id: number; title: string; url: string; quote: string; body: string; tags: string[]; preview: string; indexedAt: string };
type SessionTab = { title: string; url: string; closedAt?: string };
type TabSession = { tabs: SessionTab[]; activeUrl: string; recentlyClosed: SessionTab[] };
type CrawlResult = { indexed: number; skipped: number; failed: number; message: string };
type CrawlProgress = { jobId: string; indexed: number; skipped: number; failed: number; queued: number; limit: number; currentUrl?: string; status: "running" | "cancelled" | "complete" };
type PublicSearchResult = { title: string; url: string; preview: string; indexedAt: string; score: number };
type PublicSearchResponse = { query: string; sort: "relevance" | "newest"; domain: string | null; from: string | null; to: string | null; language: string | null; documentType: string | null; page: number; pageSize: number; total: number; totalPages: number; results: PublicSearchResult[]; facets: { domains: Array<{ domain: string; count: number }>; dates: Array<{ date: string; count: number }> }; source: string };
type PublicSearchSuggestion = { value: string; label: string; kind: "title" | "domain" };
type CrawlPolicy = { maxDepth?: number; requestIntervalMs?: number; includePatterns: string[]; excludePatterns: string[]; allowedContentTypes?: string[] };
type PublicCrawlJob = { id: string; seedUrl: string; maxPages: number; allowedHosts: string[]; policy?: CrawlPolicy; recrawlMinutes?: number; nextRecrawlAt?: number; status: "queued" | "running" | "paused" | "complete" | "cancelled" | "failed"; indexed: number; skipped: number; failed: number; skipReasons?: Record<string, number>; createdAt: string; updatedAt: string; error?: string };
type PublicFrontier = { total: number; states: Record<"queued" | "processing" | "fetched" | "failed", number>; attempted: number; attempts: number; retries: number };
type PublicFrontierEntry = { url: string; state: "queued" | "processing" | "fetched" | "failed"; attempts: number; depth: number; lastError?: string | null };
type PublicOperationalMetrics = { generatedAt: string; database: { bytes: number; schemaVersion: number }; documents: { total: number; languages: Array<{ language: string; count: number }>; types: Array<{ documentType: string; count: number }> }; jobs: { total: number; statuses: Record<string, number> }; frontier: { total: number; states: Record<string, number>; retrying: number; retries: number; failed: number } };
type PublicDomainBlock = { domain: string; reason: string; createdAt: string; updatedAt: string };
type PublicBackupSnapshot = { file: string; bytes: number; modifiedAt: string };
type PublicBackupVerification = PublicBackupSnapshot & { verifiedAt: string; integrity: "ok"; schemaVersion: number; compatible: boolean; documents: number; jobs: number; frontier: number; domainBlocks: number };
type SupabaseConfig = { url: string; anonKey: string };
type SupabaseSession = { access_token: string; user: { id: string; email?: string } };
type DownloadStatus = { id: string; name: string; state: "starting" | "progressing" | "complete" | "cancelled" | "interrupted"; received: number; total: number; path?: string };
type BrowserStore = { load(): Promise<{ bookmarks: Bookmark[]; readingList?: ReadingItem[]; savedSearches?: SavedSearch[]; searchHistory?: SearchHistoryItem[]; history: HistoryItem[] }>; loadSession(): Promise<TabSession>; saveSession(session: TabSession): Promise<void>; toggleBookmark(item: Bookmark): Promise<Bookmark[]>; toggleReadingList(item: ReadingItem): Promise<ReadingItem[]>; toggleSavedSearch(item: SavedSearch): Promise<SavedSearch[]>; addSearchHistory(item: SearchHistoryItem): Promise<SearchHistoryItem[]>; clearSearchHistory(): Promise<SearchHistoryItem[]>; addHistory(item: HistoryItem): Promise<HistoryItem[]>; indexDocument(item: IndexedDocument): Promise<number>; documentCount(): Promise<number>; graph(): Promise<GraphData>; search(query: string, page?: number): Promise<{ results: SearchResult[]; total: number; page: number; pageSize: number; totalPages: number; error?: string }>; publicSearchConfig(): Promise<{ endpoint: string; adminToken: string } | undefined>; supabaseConfig(): Promise<SupabaseConfig | undefined>; mergeSupabaseState(state: { bookmarks: Bookmark[]; readingList: ReadingItem[]; savedSearches: SavedSearch[] }): Promise<{ bookmarks: Bookmark[]; readingList: ReadingItem[]; savedSearches: SavedSearch[] }>; crawl(request: { jobId?: string; url: string; maxPages?: number; sameHost?: boolean }): Promise<CrawlResult>; cancelCrawl(jobId: string): Promise<boolean>; onCrawlProgress(listener: (progress: CrawlProgress) => void): () => void; notes(): Promise<Note[]>; saveNote(note: Omit<Note, "id" | "createdAt">): Promise<Note>; updateNote(note: Pick<Note, "id" | "body" | "tags">): Promise<Note>; deleteNote(id: number): Promise<void>; exportBackup(): Promise<{ cancelled: boolean; path?: string }>; importBackup(): Promise<{ cancelled: boolean; documents?: number; notes?: number }>; onDownloadUpdate(listener: (download: DownloadStatus) => void): () => void };
