interface Window { browserStore: BrowserStore; windowControls: WindowControls }

type Webview = HTMLElement & { partition: string; src: string; loadURL(url: string): void; getURL(): string; goBack(): void; goForward(): void; reload(): void; findInPage(text: string, options?: { forward?: boolean; findNext?: boolean }): void; stopFindInPage(action: "clearSelection" | "keepSelection" | "activateSelection"): void; setZoomFactor(factor: number): void; executeJavaScript(script: string): Promise<any> };
